// @ts-nocheck
import * as THREE from "three";

function makeCanvas(w, h) {
  const canvas = document.createElement('canvas');
  canvas.width = w;
  canvas.height = h;
  return { canvas, ctx: canvas.getContext('2d') };
}

function drawStar(ctx, cx, cy, outer, inner, points = 5, rotation = -Math.PI / 2) {
  ctx.beginPath();
  for (let i = 0; i < points * 2; i++) {
    const radius = i % 2 === 0 ? outer : inner;
    const angle = rotation + (i * Math.PI) / points;
    const x = cx + Math.cos(angle) * radius;
    const y = cy + Math.sin(angle) * radius;
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  }
  ctx.closePath();
  ctx.fill();
}

/* Myanmar flag + white star decal textures — shared by every rebuild. */
function makeFlagTexture() {
  const { canvas, ctx } = makeCanvas(256, 170);
  const band = 170 / 3;
  const colors = ['#fecb00', '#34b233', '#ea2839'];
  colors.forEach((color, i) => {
    ctx.fillStyle = color;
    ctx.fillRect(0, Math.round(i * band), 256, Math.ceil(band));
  });
  ctx.fillStyle = '#ffffff';
  drawStar(ctx, 128, 85, 40, 16, 5);
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 4;
  return tex;
}

function makeStarTexture() {
  const { canvas, ctx } = makeCanvas(256, 256);
  ctx.clearRect(0, 0, 256, 256);
  ctx.save();
  ctx.shadowColor = 'rgba(0,0,0,0.45)';
  ctx.shadowBlur = 8;
  ctx.fillStyle = 'rgba(255,255,255,0.96)';
  drawStar(ctx, 128, 128, 104, 42, 5);
  ctx.restore();
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 4;
  return tex;
}

let _FLAG_TEX;
const FLAG_TEX = () => (_FLAG_TEX ??= makeFlagTexture());
let _STAR_TEX;
const STAR_TEX = () => (_STAR_TEX ??= makeStarTexture());

const flat = (color, roughness = 0.72, metalness = 0.16) =>
  new THREE.MeshStandardMaterial({ color, roughness, metalness, flatShading: true });

function box(w, h, d, mat, name) {
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
  if (name) mesh.name = name;
  return mesh;
}

function cyl(rTop, rBottom, h, segments, mat, name) {
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(rTop, rBottom, h, segments), mat);
  if (name) mesh.name = name;
  return mesh;
}

function put(mesh, x, y, z, rx = 0, ry = 0, rz = 0) {
  mesh.position.set(x, y, z);
  mesh.rotation.set(rx, ry, rz);
  return mesh;
}

function decal(texture, w, h, name) {
  const isStar = texture === STAR_TEX();
  const mat = new THREE.MeshStandardMaterial({
    map: texture,
    roughness: 0.78,
    metalness: 0.04,
    side: THREE.DoubleSide,
    transparent: isStar,
    alphaTest: isStar ? 0.35 : 0,
    depthWrite: !isStar
  });
  const mesh = new THREE.Mesh(new THREE.PlaneGeometry(w, h), mat);
  mesh.name = name;
  mesh.castShadow = false;
  mesh.receiveShadow = false;
  return mesh;
}

